    const afterPerimeter = trianglePerimeter(triangles, vertices);

    assert.equal(triangles.length, length);
    assert.ok(afterPerimeter < beforePerimeter * 0.9);
    assert.equal(deviation(vertices, null, 2, triangles), 0);
});

