function stats(t,v,dim=2){let minA=180,minQ=1,sumQ=0,bad=0,zero=0,per=0;for(let i=0;i<t.length;i+=3){const xs=[],ys=[];for(let k=0;k<3;k++){xs.push(v[t[i+k]*dim]);ys.push(v[t[i+k]*dim+1]);}const a=Math.hypot(xs[1]-xs[0],ys[1]-ys[0]),b=Math.hypot(xs[2]-xs[1],ys[2]-ys[1]),c=Math.hypot(xs[0]-xs[2],ys[0]-ys[2]);const ar=Math.abs((xs[1]-xs[0])*(ys[2]-ys[0])-(ys[1]-ys[0])*(xs[2]-xs[0]))/2;const q=4*Math.sqrt(3)*ar/(a*a+b*b+c*c);if(ar===0)zero++;if(q<0.1)bad++;if(q<minQ)minQ=q;sumQ+=q;per+=a+b+c; const aa=(a,b,c)=>Math.acos(Math.max(-1,Math.min(1,(b*b+c*c-a*a)/(2*b*c))))*180/Math.PI; minA=Math.min(minA,aa(a,b,c),aa(b,c,a),aa(c,a,b));}return {n:t.length/3,bad,zero,minQ,minA,mean:sumQ/(t.length/3),per};}
const rows=[];for(const id of ids){const coords=JSON.parse(fs.readFileSync(`test/fixtures/${id}.json`));const d=flatten(coords);let t;try{t=earcut(d.vertices,d.holes,d.dimensions);}catch(e){console.log('ERR',id,e.message);continue;}const s=stats(t,d.vertices,d.dimensions);if(s.bad||s.minQ<0.05)rows.push([id,s,deviation(d.vertices,d.holes,d.dimensions,t),coords.length-1]);}
rows.sort((a,b)=>b[1].bad-a[1].bad);for(const [id,s,dev,holes] of rows.slice(0,35))console.log(id.padEnd(22), 'tris',String(s.n).padStart(5),'bad',String(s.bad).padStart(4),'minQ',s.minQ.toFixed(4),'minA',s.minA.toFixed(2),'mean',s.mean.toFixed(3),'dev',dev.toExponential(1),'holes',holes);
EOF", "justification": "", "login": false, "max_output_tokens": 20000, "prefix_rule": [], "sandbox_permissions": "use_default", "shell": "bash", "tty": false, "workdir": "/home/dev/feedback/uid26323", "yield_time_ms": 30000}

