/** @type {Node[]} */
const splitStack = [];

// set by filterPoints whenever it removes at least one node; read by earcutLinked's stall
// handler to decide whether another clip pass is worth attempting before the costlier stages
let filteredOut = false;

// max-heap of candidate ears ordered by normalized triangle quality. The heap makes the clipper
// deterministic without following ring order, which otherwise strands long, nearly collinear
// triangles until the end of a pass. Entries are validated lazily: a node version bump means its
// prev/next changed, and a node that was blocked by a point inside its ear is reconsidered by the
// full scan after the heap drains.
/** @type {Node[]} */
const earHeap = [];
/** @type {number[]} */
const earScore = [];
/** @type {number[]} */
const earVersion = [];
let earHeapSize = 0;
let poppedVersion = 0;

/**
 * Triangulate a polygon given as a flat array of vertex coordinates.
 *
 * @param {ArrayLike<number>} data flat array of vertex coordinates
 * @param {ArrayLike<number> | null} [holeIndices] indices (in vertices, not coordinates) where each hole ring starts
 * @param {number} [dim=2] number of coordinates per vertex in `data`
 * @returns {number[]} triangles as triplets of vertex indices into `data`
 * @example earcut([10,0, 0,50, 60,60, 70,10]); // [1,0,3, 3,2,1]
 */
export default function earcut(data, holeIndices, dim = 2) {

    const hasHoles = holeIndices && holeIndices.length;
    const outerLen = hasHoles ? holeIndices[0] * dim : data.length;
    if (steiners.size) steiners.clear();

    let outerNode = linkedList(data, 0, outerLen, dim, true);
    /** @type {number[]} */
    const triangles = [];

    if (!outerNode || outerNode.next === outerNode.prev) return triangles;

    let minX = 0, minY = 0, invSize = 0;

    if (hasHoles) outerNode = eliminateHoles(data, holeIndices, outerNode, dim);

    // if the shape is not too simple, we'll use z-order curve hash later; calculate polygon bbox
    if (data.length > 80 * dim) {
        minX = data[0];
        minY = data[1];
        let maxX = minX;
        let maxY = minY;

        for (let i = dim; i < outerLen; i += dim) {
            const x = data[i];
            const y = data[i + 1];
            if (x < minX) minX = x;
            if (y < minY) minY = y;
            if (x > maxX) maxX = x;
            if (y > maxY) maxY = y;
        }

        // minX, minY and invSize are later used to transform coords into integers for z-order calculation
        invSize = Math.max(maxX - minX, maxY - minY);
        invSize = invSize !== 0 ? 32767 / invSize : 0;
    }

    earcutLinked(outerNode, triangles, minX, minY, invSize);
    while (splitStack.length) earcutLinked(/** @type {Node} */ (splitStack.pop()), triangles, minX, minY, invSize);

    return triangles;
}

// create a circular doubly linked list from polygon points in the specified winding order
/** @param {ArrayLike<number>} data @param {number} start @param {number} end @param {number} dim @param {boolean} clockwise @returns {Node | null} */
function linkedList(data, start, end, dim, clockwise) {
    /** @type {Node | null} */
    let last = null;
    const order = repairRing(data, start, end, dim);

    if (order) {
            const node = popEar();
            if (node.v !== poppedVersion || node.prev.next !== node || !isConvexAt(node)) continue;
            if (!convex && !(invSize ? isEarHashed(node, minX, minY, invSize) : isEar(node))) continue;

            const prev = node.prev;
            const next = node.next;
            triangles.push(prev.i, node.i, next.i);
            removeNode(node);
            pushEar(prev);
            pushEar(next);
            ear = next;
        }

        if (ear.prev === ear.next) break;

        // Queued candidates can be invalidated by blockers that were subsequently removed, so
        // once the heap drains, do a full pass that only re-queues ears valid in the current ring.
        filteredOut = false;
        ear = filterPoints(ear);
        if (filteredOut) continue;

        const best = findBestEar(ear, minX, minY, invSize);
        if (best) {
            const prev = best.prev;
            const next = best.next;
            triangles.push(prev.i, best.i, next.i);
            removeNode(best);
            ear = next;
            continue;
        }

        // Filtering is exhausted and no valid ear remains: cure small local self-intersections
        // once, then split as a last resort.
        if (!cured) {
            ear = cureLocalIntersections(ear, triangles);
            cured = true;
    do {
        pushEar(p);
        p = p.next;
    } while (p !== start);
}

/** @param {Node} p */
function pushEar(p) {
    if (!isConvexAt(p)) return;
    const score = quality(p);

    let i = earHeapSize++;
    while (i > 0) {
        const parent = (i - 1) >> 1;
        if (earScore[parent] >= score) break;
        earHeap[i] = earHeap[parent];
        earScore[i] = earScore[parent];
        i = parent;
    }
    earHeap[i] = p;
    earScore[i] = score;

